using System.Collections.Generic; using UnityEngine; using ERO.Data;
namespace ERO.Systems { public sealed class LocalizationSystem:MonoBehaviour { public Language Current{get;private set;} readonly Dictionary<string,Dictionary<Language,string>> db=new Dictionary<string,Dictionary<Language,string>>(); public System.Action<Language> Changed; void Awake(){Current=(Language)PlayerPrefs.GetInt("ERO.Language",0); Seed();} public void SetLanguage(Language l){Current=l;PlayerPrefs.SetInt("ERO.Language",(int)l);PlayerPrefs.Save();Changed?.Invoke(l);} public string T(string key){Dictionary<Language,string> x;if(db.TryGetValue(key,out x)&&x.TryGetValue(Current,out var v))return v;return key;} void Seed(){Add("PLAY", "JOUER","PLAY","SPIELEN","JUGAR","GIOCA","SPELEN","JOGAR","プレイ","플레이","开始游戏");Add("CREATE","CRÉER LE PERSONNAGE","CREATE CHARACTER","CHARAKTER ERSTELLEN","CREAR PERSONAJE","CREA PERSONAGGIO","PERSONAGE MAKEN","CRIAR PERSONAGEM","キャラクター作成","캐릭터 생성","创建角色");Add("LANGUAGE","LANGUE","LANGUAGE","SPRACHE","IDIOMA","LINGUA","TAAL","IDIOMA","言語","언어","语言");} void Add(string k,params string[] v){var d=new Dictionary<Language,string>();for(int i=0;i<v.Length;i++)d[(Language)i]=v[i];db[k]=d;} } }
